// Generated by url2apk. A dependency-free WKWebView wrapper. Settings live in Config.swift.

import Network
import UIKit
import WebKit

@main
final class AppDelegate: UIResponder, UIApplicationDelegate {
    func application(
        _ application: UIApplication,
        didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?
    ) -> Bool {
        return true
    }

    func application(
        _ application: UIApplication,
        configurationForConnecting connectingSceneSession: UISceneSession,
        options: UIScene.ConnectionOptions
    ) -> UISceneConfiguration {
        let configuration = UISceneConfiguration(name: "Default", sessionRole: connectingSceneSession.role)
        configuration.delegateClass = SceneDelegate.self
        return configuration
    }
}

@objc(SceneDelegate)
final class SceneDelegate: UIResponder, UIWindowSceneDelegate {
    var window: UIWindow?

    func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options connectionOptions: UIScene.ConnectionOptions) {
        guard let windowScene = scene as? UIWindowScene else { return }
        let window = UIWindow(windowScene: windowScene)
        window.rootViewController = WebViewController()
        window.makeKeyAndVisible()
        self.window = window
    }
}

extension UIColor {
    convenience init(argb: UInt32) {
        self.init(
            red: CGFloat((argb >> 16) & 0xFF) / 255,
            green: CGFloat((argb >> 8) & 0xFF) / 255,
            blue: CGFloat(argb & 0xFF) / 255,
            alpha: CGFloat((argb >> 24) & 0xFF) / 255
        )
    }
}

final class WebViewController: UIViewController, WKNavigationDelegate, WKUIDelegate, WKDownloadDelegate {
    private var webView: WKWebView!
    private let progressView = UIProgressView(progressViewStyle: .bar)
    private let errorView = UIView()
    private var progressObservation: NSKeyValueObservation?
    private let pathMonitor = NWPathMonitor()
    private var isOnline = true
    private var failingURL: URL?
    private var downloadDestinations: [ObjectIdentifier: URL] = [:]

    override var preferredStatusBarStyle: UIStatusBarStyle {
        Config.lightStatusBar ? .darkContent : .lightContent
    }
    override var prefersStatusBarHidden: Bool { Config.fullscreen }
    override var prefersHomeIndicatorAutoHidden: Bool { Config.fullscreen }
    override var supportedInterfaceOrientations: UIInterfaceOrientationMask { Config.orientations }

    deinit {
        pathMonitor.cancel()
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        // The area behind the status bar shows the theme color, like the Android app.
        view.backgroundColor = Config.fullscreen ? Config.backgroundColor : Config.themeColor

        pathMonitor.pathUpdateHandler = { [weak self] path in
            let online = path.status == .satisfied
            DispatchQueue.main.async { self?.isOnline = online }
        }
        pathMonitor.start(queue: DispatchQueue(label: "url2apk.network"))

        setUpWebView()
        setUpProgressView()
        setUpErrorView()
        load(Config.startURL)
    }

    override func viewDidAppear(_ animated: Bool) {
        super.viewDidAppear(animated)
        UIApplication.shared.isIdleTimerDisabled = Config.keepScreenOn
    }

    // MARK: - Setup

    private func setUpWebView() {
        let configuration = WKWebViewConfiguration()
        configuration.websiteDataStore = .default()
        configuration.allowsInlineMediaPlayback = true
        configuration.mediaTypesRequiringUserActionForPlayback = []
        configuration.defaultWebpagePreferences.allowsContentJavaScript = Config.javascript
        configuration.preferences.javaScriptCanOpenWindowsAutomatically = true
        if #available(iOS 16.4, *) {
            configuration.preferences.isElementFullscreenEnabled = true
        }
        if !Config.userAgentSuffix.isEmpty {
            // Keeps Safari's default "Mobile/..." token and appends the suffix.
            configuration.applicationNameForUserAgent = "Mobile/15E148 " + Config.userAgentSuffix
        }
        if Config.zoom {
            configuration.ignoresViewportScaleLimits = true
        } else {
            let source = """
            (function() {
              var extra = 'maximum-scale=1, user-scalable=no';
              var meta = document.querySelector('meta[name=viewport]');
              if (meta) {
                meta.setAttribute('content', (meta.getAttribute('content') || '') + ', ' + extra);
              } else if (document.head) {
                meta = document.createElement('meta');
                meta.name = 'viewport';
                meta.content = 'width=device-width, initial-scale=1, ' + extra;
                document.head.appendChild(meta);
              }
            })();
            """
            configuration.userContentController.addUserScript(
                WKUserScript(source: source, injectionTime: .atDocumentEnd, forMainFrameOnly: true)
            )
        }

        let webView = WKWebView(frame: .zero, configuration: configuration)
        webView.navigationDelegate = self
        webView.uiDelegate = self
        webView.allowsBackForwardNavigationGestures = true
        webView.isOpaque = false
        webView.backgroundColor = Config.backgroundColor
        webView.scrollView.backgroundColor = Config.backgroundColor
        if !Config.userAgent.isEmpty {
            webView.customUserAgent = Config.userAgent
        }
        if #available(iOS 16.4, *) {
            webView.isInspectable = Config.debugWebView
        }
        if Config.pullToRefresh {
            let refresh = UIRefreshControl()
            refresh.tintColor = Config.progressColor
            refresh.addTarget(self, action: #selector(pulledToRefresh(_:)), for: .valueChanged)
            webView.scrollView.refreshControl = refresh
        }

        webView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(webView)
        NSLayoutConstraint.activate([
            webView.topAnchor.constraint(equalTo: Config.fullscreen ? view.topAnchor : view.safeAreaLayoutGuide.topAnchor),
            webView.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            webView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            webView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
        ])
        self.webView = webView
    }

    private func setUpProgressView() {
        progressView.progressTintColor = Config.progressColor
        progressView.trackTintColor = .clear
        progressView.isHidden = true
        progressView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(progressView)
        NSLayoutConstraint.activate([
            progressView.topAnchor.constraint(equalTo: webView.topAnchor),
            progressView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            progressView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            progressView.heightAnchor.constraint(equalToConstant: 3),
        ])
        progressObservation = webView.observe(\.estimatedProgress, options: [.new]) { [weak self] webView, _ in
            guard let self = self else { return }
            let progress = Float(webView.estimatedProgress)
            self.progressView.setProgress(progress, animated: progress > self.progressView.progress)
            self.progressView.isHidden = progress >= 1
        }
    }

    private func setUpErrorView() {
        let textColor: UIColor = Config.lightBackground ? UIColor(white: 0.13, alpha: 1) : .white

        let title = UILabel()
        title.text = Config.offlineTitle
        title.font = .preferredFont(forTextStyle: .title2)
        title.textColor = textColor
        title.textAlignment = .center
        title.numberOfLines = 0

        let message = UILabel()
        message.text = Config.offlineMessage
        message.font = .preferredFont(forTextStyle: .body)
        message.textColor = textColor.withAlphaComponent(0.7)
        message.textAlignment = .center
        message.numberOfLines = 0

        let retry = UIButton(type: .system)
        retry.setTitle(Config.retryText, for: .normal)
        retry.titleLabel?.font = .preferredFont(forTextStyle: .headline)
        retry.setTitleColor(Config.lightTheme ? UIColor(white: 0.13, alpha: 1) : .white, for: .normal)
        retry.backgroundColor = Config.themeColor
        retry.layer.cornerRadius = 8
        retry.contentEdgeInsets = UIEdgeInsets(top: 12, left: 28, bottom: 12, right: 28)
        retry.addTarget(self, action: #selector(retryTapped), for: .touchUpInside)

        let stack = UIStackView(arrangedSubviews: [title, message, retry])
        stack.axis = .vertical
        stack.alignment = .center
        stack.spacing = 16
        stack.setCustomSpacing(28, after: message)
        stack.translatesAutoresizingMaskIntoConstraints = false

        errorView.backgroundColor = Config.backgroundColor
        errorView.isHidden = true
        errorView.translatesAutoresizingMaskIntoConstraints = false
        errorView.addSubview(stack)
        view.addSubview(errorView)
        NSLayoutConstraint.activate([
            errorView.topAnchor.constraint(equalTo: webView.topAnchor),
            errorView.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            errorView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            errorView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            stack.centerYAnchor.constraint(equalTo: errorView.safeAreaLayoutGuide.centerYAnchor),
            stack.leadingAnchor.constraint(equalTo: errorView.safeAreaLayoutGuide.leadingAnchor, constant: 32),
            stack.trailingAnchor.constraint(equalTo: errorView.safeAreaLayoutGuide.trailingAnchor, constant: -32),
        ])
    }

    // MARK: - Loading

    private func load(_ url: URL) {
        // Offline: serve cached pages when we have them instead of failing outright.
        let policy: URLRequest.CachePolicy = isOnline ? .useProtocolCachePolicy : .returnCacheDataElseLoad
        webView.load(URLRequest(url: url, cachePolicy: policy))
    }

    @objc private func retryTapped() {
        errorView.isHidden = true
        load(failingURL ?? webView.url ?? Config.startURL)
    }

    @objc private func pulledToRefresh(_ sender: UIRefreshControl) {
        if errorView.isHidden && webView.url != nil {
            webView.reload()
        } else {
            retryTapped()
        }
    }

    private func endRefreshing() {
        webView.scrollView.refreshControl?.endRefreshing()
    }

    private func showError(for error: Error) {
        let nsError = error as NSError
        // Cancelled loads, and loads we turned into downloads or handed to other apps.
        if nsError.domain == NSURLErrorDomain && nsError.code == NSURLErrorCancelled { return }
        if nsError.domain == "WebKitErrorDomain" && (nsError.code == 102 || nsError.code == 204) { return }
        failingURL = (nsError.userInfo[NSURLErrorFailingURLErrorKey] as? URL) ?? webView.url
        errorView.isHidden = false
        progressView.isHidden = true
        endRefreshing()
    }

    // MARK: - Link handling

    private static func isHTTP(_ url: URL) -> Bool {
        let scheme = url.scheme?.lowercased() ?? ""
        return scheme == "http" || scheme == "https"
    }

    private func isInternalHost(_ host: String?) -> Bool {
        guard let host = host?.lowercased() else { return true }
        return Config.allowedHosts.contains { allowed in
            allowed == "*" || host == allowed || host.hasSuffix("." + allowed)
        }
    }

    private func openExternal(_ url: URL) {
        UIApplication.shared.open(url, options: [:]) { [weak self] opened in
            if !opened { self?.alert("No app found to open this link") }
        }
    }

    func webView(
        _ webView: WKWebView,
        decidePolicyFor navigationAction: WKNavigationAction,
        decisionHandler: @escaping (WKNavigationActionPolicy) -> Void
    ) {
        guard let url = navigationAction.request.url else { return decisionHandler(.cancel) }
        if navigationAction.shouldPerformDownload {
            return decisionHandler(Config.downloads ? .download : .cancel)
        }
        let scheme = url.scheme?.lowercased() ?? ""
        let isMainFrame = navigationAction.targetFrame?.isMainFrame ?? true
        let userInitiated = navigationAction.navigationType == .linkActivated
            || navigationAction.navigationType == .formSubmitted

        if Self.isHTTP(url) {
            // Redirects, scripted navigations and subframes stay in the app; only
            // links the user follows to another site go to the browser.
            if !isMainFrame || !userInitiated || !Config.openExternalLinks || isInternalHost(url.host) {
                return decisionHandler(.allow)
            }
            openExternal(url)
            return decisionHandler(.cancel)
        }
        if ["about", "javascript", "data", "blob", "file", ""].contains(scheme) {
            return decisionHandler(.allow)
        }
        // tel:, mailto:, sms:, maps:, itms-apps:, whatsapp:, etc. Background
        // frames may not launch other apps without a user gesture.
        if isMainFrame || userInitiated {
            openExternal(url)
        }
        decisionHandler(.cancel)
    }

    func webView(
        _ webView: WKWebView,
        decidePolicyFor navigationResponse: WKNavigationResponse,
        decisionHandler: @escaping (WKNavigationResponsePolicy) -> Void
    ) {
        if Config.downloads, navigationResponse.isForMainFrame {
            let disposition = (navigationResponse.response as? HTTPURLResponse)?
                .value(forHTTPHeaderField: "Content-Disposition")?.lowercased() ?? ""
            if !navigationResponse.canShowMIMEType || disposition.hasPrefix("attachment") {
                return decisionHandler(.download)
            }
        }
        decisionHandler(.allow)
    }

    func webView(_ webView: WKWebView, didStartProvisionalNavigation navigation: WKNavigation!) {
        progressView.isHidden = false
    }

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        errorView.isHidden = true
        progressView.isHidden = true
        failingURL = nil
        endRefreshing()
    }

    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        showError(for: error)
    }

    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        progressView.isHidden = true
        endRefreshing()
    }

    func webViewWebContentProcessDidTerminate(_ webView: WKWebView) {
        // The web content process crashed or was killed: reload instead of showing a blank page.
        if webView.url != nil {
            webView.reload()
        } else {
            load(Config.startURL)
        }
    }

    // MARK: - Windows, dialogs and permissions

    func webView(
        _ webView: WKWebView,
        createWebViewWith configuration: WKWebViewConfiguration,
        for navigationAction: WKNavigationAction,
        windowFeatures: WKWindowFeatures
    ) -> WKWebView? {
        // target="_blank" and window.open(): internal pages open in place.
        if let url = navigationAction.request.url {
            if Self.isHTTP(url) && (!Config.openExternalLinks || isInternalHost(url.host)) {
                webView.load(navigationAction.request)
            } else if url.scheme?.lowercased() != "about" {
                openExternal(url)
            }
        }
        return nil
    }

    func webView(
        _ webView: WKWebView,
        runJavaScriptAlertPanelWithMessage message: String,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping () -> Void
    ) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler() })
        presentOrElse(alert) { completionHandler() }
    }

    func webView(
        _ webView: WKWebView,
        runJavaScriptConfirmPanelWithMessage message: String,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping (Bool) -> Void
    ) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel) { _ in completionHandler(false) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler(true) })
        presentOrElse(alert) { completionHandler(false) }
    }

    func webView(
        _ webView: WKWebView,
        runJavaScriptTextInputPanelWithPrompt prompt: String,
        defaultText: String?,
        initiatedByFrame frame: WKFrameInfo,
        completionHandler: @escaping (String?) -> Void
    ) {
        let alert = UIAlertController(title: nil, message: prompt, preferredStyle: .alert)
        alert.addTextField { $0.text = defaultText }
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel) { _ in completionHandler(nil) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { [weak alert] _ in
            completionHandler(alert?.textFields?.first?.text ?? "")
        })
        presentOrElse(alert) { completionHandler(nil) }
    }

    func webView(
        _ webView: WKWebView,
        requestMediaCapturePermissionFor origin: WKSecurityOrigin,
        initiatedByFrame frame: WKFrameInfo,
        type: WKMediaCaptureType,
        decisionHandler: @escaping (WKPermissionDecision) -> Void
    ) {
        // Granting here still shows the system camera/microphone prompt the first time.
        let allowed: Bool
        switch type {
        case .camera: allowed = Config.camera
        case .microphone: allowed = Config.microphone
        case .cameraAndMicrophone: allowed = Config.camera && Config.microphone
        @unknown default: allowed = false
        }
        decisionHandler(allowed ? .grant : .deny)
    }

    /// Presents `controller`, or runs `fallback` if something is already on screen
    /// (WebKit requires every dialog completion handler to be called).
    private func presentOrElse(_ controller: UIViewController, fallback: @escaping () -> Void) {
        guard presentedViewController == nil, view.window != nil else { return fallback() }
        present(controller, animated: true)
    }

    private func alert(_ message: String) {
        let alert = UIAlertController(title: nil, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default))
        if presentedViewController == nil { present(alert, animated: true) }
    }

    // MARK: - Downloads

    func webView(_ webView: WKWebView, navigationAction: WKNavigationAction, didBecome download: WKDownload) {
        download.delegate = self
    }

    func webView(_ webView: WKWebView, navigationResponse: WKNavigationResponse, didBecome download: WKDownload) {
        download.delegate = self
    }

    func download(
        _ download: WKDownload,
        decideDestinationUsing response: URLResponse,
        suggestedFilename: String,
        completionHandler: @escaping (URL?) -> Void
    ) {
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        } catch {
            return completionHandler(nil)
        }
        let name = suggestedFilename.isEmpty ? "download" : suggestedFilename
        let destination = directory.appendingPathComponent(name)
        downloadDestinations[ObjectIdentifier(download)] = destination
        completionHandler(destination)
    }

    func downloadDidFinish(_ download: WKDownload) {
        guard let file = downloadDestinations.removeValue(forKey: ObjectIdentifier(download)) else { return }
        // The share sheet offers "Save to Files", AirDrop, other apps, etc.
        let share = UIActivityViewController(activityItems: [file], applicationActivities: nil)
        share.popoverPresentationController?.sourceView = view
        share.popoverPresentationController?.sourceRect = CGRect(x: view.bounds.midX, y: view.bounds.midY, width: 0, height: 0)
        share.popoverPresentationController?.permittedArrowDirections = []
        if presentedViewController == nil { present(share, animated: true) }
    }

    func download(_ download: WKDownload, didFailWithError error: Error, resumeData: Data?) {
        downloadDestinations.removeValue(forKey: ObjectIdentifier(download))
        alert("Download failed: \(error.localizedDescription)")
    }
}
